#!/usr/bin/env node

/**
 * audit-board.mjs
 * 
 * This tool performs a comprehensive audit on the ranked board generated by the token radar.
 * It validates structural integrity, data consistency, and adherence to bounty gate rules.
 * 
 * Requirements:
 * - Node 22+
 * - Standard library only
 * - No network access
 */

import { readFileSync } from 'node:fs';

/**
 * Formats a number as a USD currency string with thousands separators.
 * @param {number} n - The value to format.
 * @returns {string} The formatted string.
 */
const formatUSD = (n) => {
  return '$' + Math.round(n).toLocaleString('en-US');
};

/**
 * Main audit function that executes the validation suite.
 */
function runAudit() {
  const args = process.argv.slice(2);
  
  if (args.length < 2) {
    console.error('Error: Missing arguments.');
    console.error('Usage: node scripts/audit-board.mjs <board.json> <snapshot.json>');
    process.exit(1);
  }

  const [boardFilePath, snapshotFilePath] = args;

  let boardData, snapshotData;
  try {
    // Read and parse the input JSON files
    const boardRaw = readFileSync(boardFilePath, 'utf8');
    const snapshotRaw = readFileSync(snapshotFilePath, 'utf8');
    boardData = JSON.parse(boardRaw);
    snapshotData = JSON.parse(snapshotRaw);
  } catch (err) {
    console.error(`Fatal: Failed to load or parse input files. ${err.message}`);
    process.exit(1);
  }

  // The board.json structure is { rows: BoardRow[] }
  const boardRows = boardData.rows;
  if (!Array.isArray(boardRows)) {
    console.error('Fatal: board.json does not contain a "rows" array.');
    process.exit(1);
  }

  const snapshotProtocols = snapshotData.protocols;
  const snapshotWatchlist = new Set(snapshotData.watchlist);
  const snapshotSlugs = new Set(snapshotProtocols.map(p => p.slug));

  let failureCount = 0;
  const errorLogs = [];

  /**
   * Records a validation failure and increments the error counter.
   * @param {string} message - The error description.
   */
  const recordError = (message) => {
    errorLogs.push(message);
    failureCount++;
  };

  console.log(`Auditing board with ${boardRows.length} rows against snapshot...`);

  // 1. Check Row Count: Must be between 100 and 4000
  if (boardRows.length < 100 || boardRows.length > 4000) {
    recordError(`Board size ${boardRows.length} is outside the allowed 100-4000 range.`);
  }

  // 2. Slug Validation: Every slug in the board must exist in the snapshot
  const boardSlugs = new Set();
  for (const row of boardRows) {
    if (!snapshotSlugs.has(row.slug)) {
      recordError(`Protocol slug "${row.slug}" found in board but not in snapshot.`);
    }
    
    // 3. Unique Slugs: No protocol may appear twice in the ranked board
    if (boardSlugs.has(row.slug)) {
      recordError(`Duplicate protocol slug found in board: "${row.slug}".`);
    }
    boardSlugs.add(row.slug);
  }

  // 4. Rank Consistency: Ranks must be exactly 1 to N without gaps or overlaps
  boardRows.forEach((row, index) => {
    const expectedRank = index + 1;
    if (row.rank !== expectedRank) {
      recordError(`Rank mismatch at index ${index}: expected ${expectedRank}, found ${row.rank}.`);
    }
  });

  // 5. Implied Value Ordering: Value must never increase as rank decreases (rank 1 is highest)
  for (let i = 1; i < boardRows.length; i++) {
    const currentVal = boardRows[i].implied_value_usd;
    const previousVal = boardRows[i - 1].implied_value_usd;
    if (currentVal > previousVal) {
      recordError(`Ordering violation: Rank ${boardRows[i].rank} ($${currentVal}) exceeds Rank ${boardRows[i-1].rank} ($${previousVal}).`);
    }
  }

  // 6. Value Diversity: The first and last rows must not have equal implied values
  if (boardRows.length >= 2) {
    const firstVal = boardRows[0].implied_value_usd;
    const lastVal = boardRows[boardRows.length - 1].implied_value_usd;
    if (firstVal === lastVal) {
      recordError(`Diversity failure: First and last rows share the same implied value ($${firstVal}).`);
    }
  }

  // 7. Farm Step Validation: Each row must have 3-12 steps, each 20-600 characters
  for (const row of boardRows) {
    const steps = row.farm_steps;
    if (!Array.isArray(steps) || steps.length < 3 || steps.length > 12) {
      recordError(`Protocol ${row.slug} has invalid number of farm steps: ${steps?.length}.`);
    } else {
      steps.forEach((step, idx) => {
        if (typeof step !== 'string' || step.length < 20 || step.length > 600) {
          recordError(`Protocol ${row.slug} step ${idx} length ${step?.length} is outside 20-600 range.`);
        }
      });
    }
  }

  // 8. Watchlist Coverage: Every slug on the snapshot's watchlist must be present
  for (const slug of snapshotWatchlist) {
    if (!boardSlugs.has(slug)) {
      recordError(`Watchlist protocol missing from board: "${slug}".`);
    }
  }

  // 9. Early Row Requirement: At least 60 rows must be from outside the watchlist
  const earlyCount = boardRows.filter(r => !snapshotWatchlist.has(r.slug)).length;
  if (earlyCount < 60) {
    recordError(`Insufficient early protocols: found ${earlyCount}, required at least 60.`);
  }

  // Output the audit results
  console.log('\n--- Audit Results ---');
  if (failureCount > 0) {
    console.log(`STATUS: FAILED (${failureCount} errors found)`);
    errorLogs.forEach(err => console.log(`  [FAIL] ${err}`));
  } else {
    console.log('STATUS: PASSED');
    console.log('  All structural and data integrity checks successful.');
  }

  // 10. Top 10 Summary: Formatted name and implied value
  console.log('\n--- Top 10 Protocols ---');
  const top10 = boardRows.slice(0, 10);
  top10.forEach(row => {
    console.log(`  Rank ${row.rank.toString().padStart(2)}: ${row.name.padEnd(20)} ${formatUSD(row.implied_value_usd)}`);
  });

  // 11. Board Statistics: Share of top 10
  const top10Sum = top10.reduce((acc, r) => acc + r.implied_value_usd, 0);
  const totalSum = boardRows.reduce((acc, r) => acc + r.implied_value_usd, 0);
  const top10Share = (top10Sum / totalSum) * 100;
  
  console.log('\n--- Board Statistics ---');
  console.log(`  Total Board Value: ${formatUSD(totalSum)}`);
  console.log(`  Top 10 Cumulative: ${formatUSD(top10Sum)}`);
  console.log(`  Top 10 Value Share: ${top10Share.toFixed(2)}%`);

  // Exit with appropriate code
  process.exit(failureCount > 0 ? 1 : 0);
}

// Execute the audit suite
runAudit();
